const PHYSICS_DP = [{"id": "3.1.1.1", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.1", "descriptor": "Apply vector analysis to resolve a vector into two perpendicular components.", "graphical": false, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.1.2", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.2", "descriptor": "Solve vector problems by resolving vectors into components, adding or subtracting the components and recombining them to determine the resultant vector.", "graphical": false, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.1.3", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.3", "descriptor": "Describe how horizontal and vertical components of a velocity vector are independent of each other.", "graphical": false, "needsExplanation": true, "modelAnswer": ["With air resistance neglected, horizontal and vertical motion can be analyzed separately.", "Gravity changes only the vertical component of velocity, producing a constant downward acceleration which is –g (-9.8 m/s^2).", "The horizontal component has zero acceleration and remains constant.", "Both components occur over the same time interval and combine vectorially to give the projectile's instantaneous velocity and curved trajectory.", "To find the horizontal component, multiply the initial velocity by cos θ (vₓ = v cos θ); to find the vertical component, multiply the initial velocity by sin θ (v_y = v sin θ)."]}, {"id": "3.1.1.4", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.4", "descriptor": "Solve problems involving projectile motion in the absence of drag effects using equations on the RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.1.5", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.5", "descriptor": "Interpret data relating to the horizontal distance travelled by an object projected at various angles from the horizontal.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.1", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.1", "descriptor": "Solve problems involving force due to gravity (weight) and mass using Fg=mg", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.2", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.2", "descriptor": "Describe the concept of normal force.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The normal force is a vector perpendicular (90°) contact force exerted by a surface on an object resting/pressing upon it measured in newtons (N), preventing the object from moving through the surface.", "It is related to Newton's third law as the object (and any other perpendicular force present) exerts a contact force on the surface, and the surface exerts an equal and opposite force back.", "As the magnitude of the normal force is determined by the total forces acting perpendicular to the surface, it is not always equal to an object's weight alone (especially when the surface the object is on is not horizontal)."]}, {"id": "3.1.2.3", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.3", "descriptor": "Describe the forces acting on an object on an inclined plane (e.g. force due to gravity, normal force, tension, frictional force and applied force) through the use of free-body diagrams.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Draw the object as a point or box and show only forces acting on it.", "Weight Fg = mg acts vertically downward.", "Normal force FN acts perpendicular to the plane.", "Friction acts parallel to the plane and opposes actual or impending relative motion.", "Weight may be resolved into mg sin(θ) down the plane and mg cos(θ) into the plane; these components are not extra forces.", "An inclined plane scenario features an object on a plane surface inclined at an angle (θ) to the horizontal.", "A tension force is the force exerted by a taut rope/cable/string and acts on the object, only pulling along the rope, directed away from the object.", "An applied force is exerted by an external agent, acting in the direction the agent pushes or pulls."]}, {"id": "3.1.2.4", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.4", "descriptor": "Determine the net force acting on an object on an inclined plane using vector analysis.", "graphical": false, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.5", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.5", "descriptor": "Describe the concept of uniform circular motion.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Uniform circular motion is the motion of an object in a circular path that holds a constant speed but changing velocity.", "A center-seeking (centripetal, F_c=mv²/r) force acts perpendicular to the instantaneous tangential velocity (v=2πr/T) which dictates its path and not its speed."]}, {"id": "3.1.2.6", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.6", "descriptor": "Describe the concepts of average speed and period.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Average speed is total distance travelled divided by total time, or v=dₜₒₜₐₗ/tₜₒₜₐₗ.", "As a circle’s circumference is given by 2πr, average speed of a circular revolution is given by v=2πr/T, where r is radius of circular motion (metres) and T is the period of revolution (seconds).", "T (Period) is the time taken for one complete revolution and is measured in seconds. v∝1/T or T∝1/v (Period and speed are inversely proportional).", "As f=1/T (f is frequency in Hertz), the average speed equation can also be expressed as v=2πrf"]}, {"id": "3.1.2.7", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.7", "descriptor": "Solve problems involving objects undergoing uniform circular motion at a constant speed using v=(2(pi)r)/T and ac = v^2/r", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.8", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.8", "descriptor": "Describe the concepts of centripetal acceleration and centripetal force.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Centripetal Acceleration (a_c) is the acceleration of an object moving in a uniform circular path at a constant speed (v) with the velocity direction tangential to the path. a_c acts inwards towards the center of the circle, perpendicular to the velocity.", "The velocity changing direction constantly means a_c is also always changing direction. a_c does not change the speed of the object.", "The equation is: a_c=v²/r.", "The acceleration is caused by a net external force: Friction, Gravity, and Normal Force are some examples that could supply forces contributing to the net force.", "Using Newton's Second Law (F=ma), the centripetal force (F_c) is given by F_c=mv²/r.", "This force also acts inwards towards the center of the circular motion."]}, {"id": "3.1.2.9", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.9", "descriptor": "Solve problems involving forces acting on objects in uniform circular motion using Fc = Fnet = mv^2/r", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.1", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.1", "descriptor": "Describe the Law of Universal Gravitation.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Newton’s Law of Universal Gravitation states that every object with mass attracts every other object with mass with a gravitational force measured in newtons (N).", "The force is a vector and acts along a line between both centers of the 2 masses.", "The magnitude of the force is directly proportional to the product of both masses and inversely proportional to the distance between the 2 centers of the masses, given by F =GMm/r², where G is the universal gravitational constant (6.67 × 10⁻¹¹ N m² kg⁻²), M and m are the masses measured in kilograms in kg, and r is the center-to-center separation measured in meters (m).", "The forces on the 2 masses are a Newton’s third law pair, so they are equal in magnitude and opposite in direction."]}, {"id": "3.1.3.2", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.2", "descriptor": "Solve problems involving the magnitude of the gravitational force between two masses using F = (GMm)/r^2", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.3", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.3", "descriptor": "Describe the concept of gravitational fields.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A gravitational field is the region around a mass in which another mass experiences a gravitational force.", "Gravitational field strength, g, is force per unit mass: g =F/m .", "It is measured in N/kg.", "Around a spherical mass, g =GM/r² and points toward the mass as a vector quantity.", "Field lines point inward and closer spacing represents a stronger field."]}, {"id": "3.1.3.4", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.4", "descriptor": "Solve problems involving the gravitational field strength at a distance from an object using  g = F/m = (GM)/r^2", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.5", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.5", "descriptor": "State the three laws of planetary motion.", "graphical": false, "needsExplanation": true, "modelAnswer": ["1st law (Law of Orbits/Ellipses): planets orbit the Sun in elliptical paths, with the Sun located at one focus of the ellipse (not the centre).", "2nd law (Law of Areas): a line joining a planet to the Sun sweeps out equal areas in equal time intervals — so a planet moves fastest at its closest approach (perihelion) and slowest at its furthest point (aphelion).", "3rd law (Law of Periods): the square of a planet's orbital period is directly proportional to the cube of its average orbital radius (semi-major axis): T² ∝ r³, with the same constant of proportionality for all planets orbiting the same star."]}, {"id": "3.1.3.6", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.6", "descriptor": "Describe the relationship between the Law of Universal Gravitation and uniform circular motion and recognise this as the third law of planetary motion.", "graphical": false, "needsExplanation": true, "modelAnswer": ["For a circular orbit, gravitational force provides the required centripetal force: Thus, F_G=F_C, or GMm/r²=mv²/r.", "By substituting v=2πr/T into the right and simplifying, the relationship T²/r³=4π²/GM can be obtained.", "Given that 4π²/GM is the same for different masses orbiting the same central body, T_A²/r_A³=T_B²/r_B³.", "Therefore, for bodies orbiting the same central mass, T²∝r³, where T is the period of orbit (seconds), and r is the radius of orbit (metres, from the centres of mass).", "This is Kepler’s 3ʳᵈ Law of planetary motion."]}, {"id": "3.1.3.7", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.7", "descriptor": "Solve problems involving the third law of planetary motion using Ta^2/ra^3 = Tb^2/rb^3 = 4(PI)^2/(GM)", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.1", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.1", "descriptor": "Describe Coulomb’s Law.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The magnitude of the force of electrostatic attraction (between positive and negative charges) or repulsion (between positive and positive or negative and negative charges) experienced between two point charges is directly proportional to the product of their charges and inversely proportional to the square of the distance between them.", "This is described by the equation F_E=kqQ/r²", "Where: F_E=the electrostatic force (N)", "k=a proportionality constant=9×10⁹Nm²C⁻²", "q, Q=the respective charges (C)", "r=the distance between point charges (m)", "Note that by Coulomb’s shell theorem, two non-point charges whose radii do not overlap can be treated as point charges"]}, {"id": "3.2.1.2", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.2", "descriptor": "Solve problems using Coulomb's Law Equation", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.3", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.3", "descriptor": "Describe the concepts of electric fields, electric field strength and electrical potential energy.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An electric field is a region around a charged object where other charged objects experience an electric force.", "Electric field strength is force per unit positive test charge N/C: E =F/q, with direction defined by the force on a positive test charge.", "Electrical potential energy is the potential of a charged object to do work based on its position within an electric field."]}, {"id": "3.2.1.4", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.4", "descriptor": "Solve problems involving electric field strength using equation", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.5", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.5", "descriptor": "Solve problems involving the work done when an electric charge is moved in an electric field using equation", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.1", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.1", "descriptor": "Describe the concept of a magnetic field.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A magnetic field is a region surrounding a magnetic, moving electric charge, or changing electric field in which magnetic force can be felt.", "Field direction is the direction a north magnetic pole would move.", "The field runs from the north pole to the south pole.", "The field is represented by the vector B and is measured in tesla (T)."]}, {"id": "3.2.2.2", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.2", "descriptor": "Sketch magnetic field lines due to a moving electric charge, electric currents and magnets.", "graphical": false, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.3", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.3", "descriptor": "Describe the generation of a magnetic field from a moving electric charge.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A moving electric charge generates a magnetic field which forms concentric circles around the direction of motion of the electric charge.", "The direction of the field is defined by the right-hand rule in which the thumb of the right-hand points in the direction of motion of the charge and the fingers curl to show the direction of the magnetic field.", "The magnetic field is represented by the symbol B and is measured in tesla (T).", "The strength of the field is defined by the equation:", "B=μ₀I/2πr", "Where μ₀ is the magnetic permeability of free space, I is the current, and r is the perpendicular distance from the moving charge."]}, {"id": "3.2.2.4", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.4", "descriptor": "Solve problems involving the magnitude and direction of magnetic fields around a straight electric current-carrying wire and inside a solenoid using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.5", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.5", "descriptor": "Describe the force experienced by electric current-carrying conductors and moving electric charges when placed in a magnetic field.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In a uniform magnetic field, the force experienced by a straight current carrying conductor is given by F=BIL sin θ where F=the force on the wire (N), B=the magnetic field's magnetic field strength (T), I=the current in the wire(A), L=the length of the wire inside the field(m), θ=the angle between the vectors B⃑ and L⃑(°) where L’s direction follows the direction of the conventional current.", "F is perpendicular to both B and L and is formally their cross product (L⃑×B⃑).", "For a moving charge, the force acting on it in a uniform magnetic field is given by F=qvB sin θ where F is the force (N) acting on the charge, perpendicular to both v and B (v⃑×B⃑), q=the charge (C); note that negative charges result in an F of opposite direction to positive charges. v=the charge's speed (ms⁻¹), B=the magnetic field strength (T)"]}, {"id": "3.2.2.6", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.6", "descriptor": "Solve problems involving the magnetic force on an electric current-carrying wire and moving charge in a magnetic field using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.7", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.7", "descriptor": "Interpret data relating to the force acting on a conductor in a magnetic field.", "graphical": true, "needsExplanation": true, "modelAnswer": ["Identify the variables plotted (e.g. force vs current, or force vs conductor length) and describe the relationship shown — typically linear/directly proportional, consistent with F = BIL sin θ at fixed B, L and θ.", "Determine the gradient of a linear graph and relate it to the physical quantity it represents (e.g. the gradient of a force–current graph equals BL sin θ, so B can be extracted if L and θ are known).", "Use the graph (interpolation/extrapolation, or the gradient) to calculate an unknown quantity such as magnetic flux density B, and comment on the reliability of the result (line of best fit, scatter of data points, size of uncertainty).", "Note any limitations of the data or method — e.g. a non-zero y-intercept suggesting a systematic error, or a restricted range of current values tested."]}, {"id": "3.2.2.8", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.8", "descriptor": "Interpret data relating to the strength of a magnet at various distances.", "graphical": true, "needsExplanation": true, "modelAnswer": ["Describe the trend shown: magnetic field strength (or force on a test object) decreases as distance from the magnet increases, typically following an inverse-square or inverse-cube relationship depending on the magnet geometry and setup.", "Recognise the relationship is non-linear on a field-strength-vs-distance graph — plotting field strength against 1/r² (or 1/r³) can linearise the data and confirm the specific relationship.", "Use the graph to interpolate or extrapolate values (with appropriate caution about extrapolating beyond the measured range), and discuss experimental limitations, such as difficulty accurately measuring field strength very close to the magnet, or background/Earth's magnetic field affecting readings."]}, {"id": "3.2.3.1", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.1", "descriptor": "Describe the concepts of magnetic flux, magnetic flux density, electromagnetic induction, electromotive force (EMF), Faraday’s Law and Lenz’s Law.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Magnetic flux, ϕ measures the magnetic field passing through a surface: ϕ=BA cos (θ), where θ is the angle between B and the plane’s normal.", "It is a vector quantity.", "It is measured in webers (Wb).", "Magnetic flux density B describes magnetic-field strength and direction, measured in Tesla of a magnetic field.", "One tesla is one weber per square metre.", "It is a vector quantity.", "Electromagnetic induction is the production of an EMF when magnetic flux linkage changes.", "EMF is energy transferred per unit charge and is measured in volts.", "Faraday's Law states that induced EMF equals the negative rate of change of magnetic flux linkage: EMF = −n (∆∅/∆t).", "A faster change or more turns produces a larger EMF.", "Lenz's Law states that the induced current produces a magnetic field that opposes the change in magnetic flux that caused it.", "The induced effect resists an increase or decrease in flux at the surface of a coil .", "The negative sign of the equation −N∆φ/∆t represents this opposition."]}, {"id": "3.2.3.2", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.2", "descriptor": "Solve problems involving the magnetic flux in an electric current-carrying loop using equation on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.3.3", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.3", "descriptor": "Describe the process of inducing an EMF across a moving conductor in a magnetic field.", "graphical": false, "needsExplanation": true, "modelAnswer": ["When a conductor moves through a magnetic field and cuts field lines, charges in the conductor experience magnetic force qvB.", "Positive and negative charges separate, producing a potential difference across the conductor.", "For a straight conductor moving perpendicular to the field, the induced EMF is ε = BLv, where B is the magnetic field strength (T), L is the length of the conductor in the field (m) and v is its speed (m/s).", "Reversing the motion or magnetic field reverses the polarity."]}, {"id": "3.2.3.4", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.4", "descriptor": "Explain how Lenz’s Law is consistent with the principle of conservation of energy.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Lenz law states that the direction of induced current always opposes the change in magnetic flux that produced the current.", "The induced current creates a magnetic field that opposes the change in flux.", "Therefore an external agent must do work to keep moving the magnet or conductor, or to keep changing the current.", "That input work is converted into electrical energy and usually thermal energy.", "If the induced field reinforced the change, the system would create increasing energy without external work, violating conservation of energy."]}, {"id": "3.2.3.5", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.5", "descriptor": "Explain how transformers work in terms of Faraday’s Law and electromagnetic induction.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An alternating current in the primary coil produces a constantly changing magnetic flux (direction and magnitude) in the iron core.", "Through the iron core, the changing flux links to the secondary coil and induces an alternating EMF to oppose the constant change of flux.", "According to faraday’s law, the rate of change of flux is proportional to the induced EMF produced.", "This means only AC will produce a continuous emf.", "For an ideal transformer, the power P=VI is constant and Vₚ/Vₛ=Nₚ/Nₛ and VₚIₚ=VₛIₛ.", "More secondary turns gives a step-up transformer; fewer gives a step-down transformer since the more turns the coil has, the less B strength each turn must produce."]}, {"id": "3.2.3.6", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.6", "descriptor": "Solve problems involving electromagnetic induction using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.3.7", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.7", "descriptor": "Describe the concept of an electromagnetic wave.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An electromagnetic wave is a self-propagating transverse wave of oscillating electric and magnetic fields that are perpendicular to one another.", "Electromagnetic waves do not require a medium and travel through a vacuum at c=3.00×10⁸ m/s, with c/λ=f."]}, {"id": "3.2.3.8", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.8", "descriptor": "Explain the relationship between oscillating electric charges and electromagnetic waves.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An accelerating or oscillating charge produces changing electric and magnetic fields.", "A changing electric field generates a magnetic field, and a changing magnetic field generates an electric field.", "These coupled disturbances propagate away from the charge as an electromagnetic wave.", "The wave frequency matches the charge's oscillation frequency, and the fields are transverse to the direction of travel."]}, {"id": "4.1.1.1", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.1", "descriptor": "Describe observations of natural phenomena that cannot be explained by classical physics, e.g. the presence of muons in the atmosphere and the momentum of high speed particles in particle accelerators.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Muons are created about 10 km above Earth, travel at roughly 0.96c, and have a mean lifetime of 2.2 μs in their own rest frame, so classical physics predicts they should decay before reaching Earth's surface, yet this is not observed.", "Special relativity explains this: in Earth’s frame, the muon’s clock runs slow (time dilation) extending its lifetime to about 7.9 μs so it can travel to Earth's surface, while in the muon’s frame the atmosphere is length contracted to about 2.8 km, so the muon can cross it before decaying."]}, {"id": "4.1.1.2", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.2", "descriptor": "Describe the concepts of frame of reference and inertial frame of reference.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A frame of reference is the perspective of an observer measuring the time and space of an event.", "Inertial frame of reference is that but the object being observed is in constant velocity."]}, {"id": "4.1.1.3", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.3", "descriptor": "State the two postulates of special relativity.", "graphical": false, "needsExplanation": true, "modelAnswer": ["1. The laws of physics are the same (invariant) in all inertial reference frames — no experiment performed entirely within an inertial frame can determine whether that frame is 'moving' or 'at rest'.", "2. The speed of light in a vacuum has the same value (c) for all observers in inertial frames, regardless of the motion of the light source or the observer measuring it."]}, {"id": "4.1.1.4", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.4", "descriptor": "Explain how motion can only be measured relative to an observer.", "graphical": false, "needsExplanation": true, "modelAnswer": ["There is no absolute state of motion, motion is measured relative to a chosen inertial frame of reference.", "As such, different frames may assign different velocities to the same object/event depending on their own motion, since all observers can consider their own inertial frame as stationary."]}, {"id": "4.1.1.5", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.5", "descriptor": "Explain the concept of simultaneity.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Two events are simultaneous in a frame if synchronised clocks at the event locations record the same time.", "Because light speed is the same for every inertial observer, observers moving relative to each other can disagree about whether spatially separated events occurred at the same time and may disagree about their order.", "Simultaneity is therefore relative, not universal."]}, {"id": "4.1.1.6", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.6", "descriptor": "Describe the consequences of the constant speed of light in a vacuum, e.g. time dilation and length contraction.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Because every inertial observer measures the same vacuum speed of light, space and time measurements must depend on relative motion.", "As an object's speed approaches the speed of light, the object experiences time slower (therefore less time experienced), compared to a relative stationary observer who experiences time dilation.", "A moving object's length parallel to its motion is measured to be shorter by a stationary observer, producing length contraction.", "Simultaneity also becomes frame-dependent."]}, {"id": "4.1.1.7", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.7", "descriptor": "Describe the concepts of time dilation, proper time interval, relativistic time interval, length contraction, proper length, relativistic length, rest mass and relativistic momentum.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Proper time intervals must be measured from the same location, e.g. from the same place inside a spaceship travelling at relativistic speeds.", "Proper time is not affected by relativistic affects", "while relativistic times is measured in different geographical locations and could be affected by time dilation", "Length contraction is the shortening of length for an object moving close to the speed of light perceived in an observing inertial frame of reference.", "Proper length (L₀) is measured by the frame where the endpoints of the object does not change positions (moving object).", "Relativistic length (L) is the length perceived by the frame where the endpoints of the object does move (observer).", "The equation: L=L₀√(1−v²/c²) where c=speed of light.", "Since g approach infinity as v approaches c, relativistic length is always smaller or equal to proper length.", "Rest mass m₀ (kg) is the measurement of an object’s mass at rest from their own FOR which will not change regardless of how fast the object is travelling.", "Momentum p=mv under non-relativistic conditions is given by p=γm₀v, where γ=1/√(1−v²/c²).", "Due to the Lorentz factor (γ) as an object’s speed approaches the speed of light in a vacuum, its momentum approaches ∞ which explains how accelerating to the the speed of light is physically impossible."]}, {"id": "4.1.1.8", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.8", "descriptor": "Describe the phenomena of time dilation and length contraction, including examples of experimental evidence of the phenomena.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Time dilation occurs with noticeable effects when an object is moving with a velocity that is moving towards relativistic speed, v≥~0.2c, and is found by multiplying the proper time (t₀) by the Lorentz factor (1/√(1−v²/c²)), which shows that at low speeds, v≪c, the Lorentz factor is essentially equal to 1, meaning classical Newtonian physics applies and relativistic changes are too small to notice.", "As v begins to approach c, the gamma factor begins to get larger at a rapidly increasing rate, approaching infinity as v approaches c.", "This can be experimentally observed through atmospheric muon survival.", "Length contraction is also equated in relation to the Lorentz factor, L=L₀√(1−v²/c²), in which relativistic length (L) appears shorter than proper length (L₀), this takes place in muon movement where in the muon’s frame of reference the atmosphere is length-contracted, allowing the surface to be reached within the muon’s proper lifetime."]}, {"id": "4.1.1.9", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.9", "descriptor": "State the mass–energy equivalence relationship.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Mass–energy equivalence: E = mc², where E is energy, m is mass, and c is the speed of light in a vacuum.", "It states mass and energy are equivalent, interchangeable forms of the same underlying physical quantity: any object with mass has an associated 'rest energy' (E₀ = m₀c²), and conversely any store of energy has an associated equivalent mass.", "Because c² is an extremely large number, even a small mass corresponds to an enormous quantity of energy — this underlies processes such as nuclear fission/fusion and particle-antiparticle annihilation, where measurable amounts of mass are converted directly into energy (or vice versa)."]}, {"id": "4.1.1.10", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.10", "descriptor": "Solve problems involving time dilations, length contraction and relativistic momentum using  equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.11", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.11", "descriptor": "Explain the implications of relativistic momentum of objects increasing as they approach the speed of light.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Relativistic momentum is given by p=γmv, where v is velocity (m/s), m is mass (kg) and γ is the Lorentz Factor, 1/√(1−v²/c²).", "As v approaches c, the speed of light (3×10⁸ m/s), γ increases without limit.", "Thus, each incremental increase in speed closer to c requires a rapidly increasing amount of energy.", "Thus, an object with non-zero mass would require infinite energy to reach c.", "Therefore, objects with mass can approach but cannot attain or exceed the speed of light in a vacuum.", "Light, which has no mass, can travel at the speed of light."]}, {"id": "4.1.1.12", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.12", "descriptor": "Explain paradoxical scenarios that may arise as a result of special relativity including the twins’ paradox, flashlights on a train, and the ladder in the barn paradox.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Twins: If a twin flies out into space at a speed close to c and doesn’t return while a twin stays on Earth, then both twins would observe the other in a relativistic frame of reference (FOR).", "Therefore, both would view the other as younger.", "If the twin in space returns to Earth, then the space twin would be in 3 different FORs, with 2 inertial frames when travelling away and towards Earth and 1 accelerating FOR when changing direction.", "The Earth twin is constantly measuring proper time, and hence the space twin would be younger when they return to Earth.", "Flashlights on a train: If a train is travelling past a platform at a velocity close to c, and when it passes the platform 2 lights at the end of the train is turned on, because all inertial observers measure each light pulse at c, an observer in the train at equal distances between the lights would see the lights turn on a the same time but an observer on the platform would see the light closest to the front be turned on before the light at the back.", "Ladder and barn: A ladder approaches a barn with two doors at a speed close to c and goes through the barn, at which the two barn doors close at the same time.", "When they are in the same FOR the length of the barn and the ladder are equal.", "In the barns FOR it measures the ladder length has contracted, while the ladders FOR measures the barn length has contracted.", "This paradox is solved when you consider the second postulate of special relativity (i.e. the speed of light is constant for all inertial FOR), where in the barns FOR it sees the two doors close at the same time, while in the ladders FOR it sees the door its travelling towards close first and the door behind it close second."]}, {"id": "4.2.2.1", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.1", "descriptor": "Explain how the double slit experiment provides evidence for the wave model of light.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Light passing through two narrow slits produces alternating bright and dark fringes.", "Waves from the slits spread through diffraction, overlap and superpose on each other.", "Constructive interference forms bright fringes where path difference is m lambda; destructive interference forms dark fringes where path difference is (m + 1/2)lambda.", "A classical stream of particles passing independently through slits would not produce this interference pattern and since interference and diffraction are properties of a wave not particle, this provides evidence for the wave model of light."]}, {"id": "4.2.2.2", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.2", "descriptor": "Describe light as an electromagnetic wave.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Light consists of oscillating electric and magnetic fields that are perpendicular to each other and to the direction of propagation.", "It is transverse, can travel through a vacuum (i.e. requires no medium to travel through), and travels at c = 3.00 × 10⁸ms⁻¹ in a vacuum.", "Its wavelength and frequency satisfy f=c/⋋.", "Interference and diffraction are evidence of its wave behaviour, where interference is when the amplitudes of the waves can be added and be either constructive or destructive interference, and where diffraction is when a wave when going through a slit curves around the edges of the slit."]}, {"id": "4.2.2.3", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.3", "descriptor": "Explain the concept of black-body radiation and the significance of the evidence it provides.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A black body is an ideal absorber and emitter whose spectrum depends only on temperature, a relationship given by λₘₐₓ=b/T.", "While radiation is emitted across as broad range of wavelengths, λₘₐₓ is the peak wavelength (highest intensity) at any given temperature, while b is Wien’s displacement constant (2.898×10⁻³) and T is temperature in Kelvin.", "Classical physics predicted the ultraviolet catastrophe: emitted intensity (and thus energy) should approach infinity at shorter wavelengths, directly contradicting experimental observations.", "Planck proposed a theory consistent with these experimental observations by proposing that oscillators exchange energy in discrete quanta E = hf.", "Thus, supporting the quantized nature of energy and the particle model of light."]}, {"id": "4.2.2.4", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.4", "descriptor": "Describe the photoelectric effect in terms of the photon.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Photoelectric effect concerns the emission of electrons from the surface of a metal, due to quantized packets of energy of light (called photons) transferring its energy to an electron.", "The energy of photons can be shown using E=hf, where h is planck’s constant, and f is the frequency of light of the photon.", "For this emission to occur, the photon has to be above the work function and the threshold frequency.", "For the photon’s energy to be above the work function, which is the minimum energy required to eject the electron from the surface of the metal, it has to also have a frequency above the threshold frequency, which is the minimum frequency of light required to eject electrons from the surface of a metal.", "This can be displayed by the equation W=hf0, where W= work function of the metal, h = planck’s constant and f0 = threshold frequency of the metal.", "To increase the photocurrent (amount of photons shone onto the metal), the intensity of the light must increase, to increase the energy of the electron once it’s emitted, the frequency of the photon must be increased."]}, {"id": "4.2.2.5", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.5", "descriptor": "Describe the concepts of threshold frequency and work function.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The work function (W or ϕ) is the minimum energy required to localize an electron from an atom’s energy shell(s).", "Threshold frequency (f₀) is the minimum frequency of the light being emitted onto the material that allows for the localization of electrons.", "Their relationship is modelled through W=h*f₀.", "Below a light frequency of f₀, regardless of the increase of intensity of the light being emitted the electron will never be emitted.", "However, at the threshold frequency, some electrons can be freed but they will have NO kinetic energy available to move away from the emitter."]}, {"id": "4.2.2.6", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.6", "descriptor": "Solve problems involving blackbody radiation and the photoelectric effect using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.2.7", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.7", "descriptor": "Compare the different models of the atom proposed by Rutherford and Bohr.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Similarities: Both models contain a small, dense, positively charged nucleus surrounded by electrons, and both describe the atom as mostly empty space.", "Differences: Rutherford's model allows electrons to orbit without fixed energies and cannot explain atomic stability or line spectra.", "Bohr's model restricts electrons to discrete, stable energy levels.", "Electrons absorb or emit photons when moving between levels, so the model explains hydrogen's line spectrum, although it is limited for multi-electron atoms."]}, {"id": "4.2.2.8", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.8", "descriptor": "Explain how Bohr’s model of the hydrogen atom integrates light quanta and atomic energy states to explain the specific wavelengths in the hydrogen line spectrum.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Bohr proposed a hydrogen model that involved discrete levels of energy where electrons may reside.", "This was formed through Max Planck’s quantization proposition that light is emitted in packets of energy called quanta.", "When the atom is excited the electron will absorb energy and “jump” to higher energy levels, then proceeds to fall to lower levels emitting specific wavelengths of energy which is visible as line spectrum."]}, {"id": "4.2.2.9", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.9", "descriptor": "Solve problems involving the line spectra of simple atoms using atomic energy states or atomic energy level diagrams using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.2.10", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.10", "descriptor": "Describe wave–particle duality of light by identifying evidence that supports the wave characteristics of light and evidence that supports the particle characteristics of light.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Wave-particle duality of light → light demonstrate properties of both waves and particles.", "Evidence for wave model: Light produces interference patterns passing through slits, suggesting wave model of light as particle model of light suggests light instead passes through slits, continuing in the same trajectory", "Evidence for particle model: The photoelectric effect demonstrates how photons emitted on a metal induce e⁻ emission.", "The wave model of light would suggest that due to light’s nature as a continuous wave, any wavelength of light could induce e⁻ emission by continuously transferring energy.", "Experimental evidence found that certain light wavelengths could not induce e⁻ emission, regardless of intensity.", "In the wave model, intensity represents energy, in amplitude, conflicting with the understanding of energy transfer to electrons.", "This suggests the particle model of light as it attributes intensity to quantity of photons, meaning energy is not affected by intensity"]}, {"id": "4.2.2.11", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.11", "descriptor": "Interpret data related to the photoelectric effect.", "graphical": true, "needsExplanation": true, "modelAnswer": ["Identify the variables typically plotted (e.g. maximum kinetic energy of emitted electrons vs frequency of incident light) and describe the relationship shown — linear once frequency exceeds the threshold frequency, and zero (no emission) below it.", "Use the x-intercept of the linear region to read off the threshold frequency f₀ for that metal, and use the gradient of the line to determine Planck's constant h, since Ek(max) = hf − φ has gradient h.", "Use the y-intercept (or the value hf₀) to determine the work function φ of the metal being tested.", "Relate the linear shape of the graph directly to Einstein's photoelectric equation, and comment on the reliability of extracted values (line of best fit, scatter, extrapolation beyond measured data)."]}, {"id": "4.3.1.1", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.1", "descriptor": "Describe the concepts of elementary particles and antiparticles.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In the Standard Model, elementary particles are the smallest known particles, of which quarks, leptons and gauge bosons are elementary matter particles.", "Quarks have 3 families (top bottom, charm strange, and up down) and make up particles with a combination of three quarks (proton = uud, each up quark has +2/3 charge, down quakrs have charge of –1/3, this is consistent with all other quarks).", "Leptons consist of electrons, neutrinos, muons, and tau’s, each with a corresponding antiparticle.", "Gauge bosons mediate the fundamental forces of weak, strong nuclear force, em force, and theoretically gravity.", "Each particle also has a corresponding antiparticle, which has the same mass and spin as the normal particle, but the antiparticle has an opposite electric charge (proton has a charge of +1, antiproton has a charge of –1) and different quantum numbers.", "Particle-antiparticle pairs can annihilate, and sufficient energy can create pairs."]}, {"id": "4.3.1.2", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.2", "descriptor": "Identify the six types of quarks.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The six quark flavours: up, down, charm, strange, top, bottom.", "Up, charm and top carry charge +⅔e; down, strange and bottom carry charge −⅓e.", "Quarks are grouped into three generations by increasing mass: (up, down), (charm, strange), (top, bottom)."]}, {"id": "4.3.1.3", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.3", "descriptor": "Describe baryons and mesons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Baryons are hadrons made from three quarks, such as the proton (uud) and neutron (udd).", "Antibaryons contain three antiquarks.", "Mesons are hadrons made from one quark and one antiquark.", "As each quark has a spin value of ½, Baryons have non-integer spin values while Mesons have integer spin values.", "Both baryons and mesons experience the strong interaction as they are composed of quarks.", "Only baryons have Baryon number (B) equal to 1, every non-baryon has a B value of 0.", "Antibaryons have a B value of -1.", "B is calculated via 1/3(n_q−n_(q̅)), where n_q represents the number of constituent quarks and n_(q̅) represents the number of constituent antiquarks."]}, {"id": "4.3.1.4", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.4", "descriptor": "Identify the six types of leptons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The six lepton flavours: electron, muon, tau, electron neutrino, muon neutrino, tau neutrino.", "The electron, muon and tau each carry charge −1e; the three corresponding neutrinos are electrically neutral.", "Like quarks, leptons are grouped into three generations by increasing mass: (electron, electron neutrino), (muon, muon neutrino), (tau, tau neutrino)."]}, {"id": "4.3.1.5", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.5", "descriptor": "Identify the four gauge bosons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The four gauge bosons: the photon (carries the electromagnetic force), the gluon (carries the strong nuclear force), and the W and Z bosons (carry the weak nuclear force).", "The graviton, a hypothesised carrier of the gravitational force, is not part of the confirmed Standard Model, since gravity is not yet successfully incorporated into it."]}, {"id": "4.3.1.6", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.6", "descriptor": "Compare the strong nuclear, weak nuclear and electromagnetic forces in terms of the gauge bosons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Similarities: All three forces are fundamental interactions represented in the Standard Model and are mediated by gauge bosons.", "Differences: The strong nuclear force is mediated by gluons and acts on particles with colour charge, including quarks.", "The weak nuclear force is mediated by W⁺, W⁻ and Z⁰ bosons, acts on quarks and leptons, and enables transformations such as beta decay.", "The electromagnetic force is mediated by photons and acts on electrically charged particles.", "The strong force is strongest at subatomic distances, the weak force has a very short range because its bosons are massive, and the electromagnetic force has infinite range and can attract or repel."]}, {"id": "4.3.1.7", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.7", "descriptor": "Contrast the fundamental forces experienced by quarks and leptons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Differences ONLY: Quarks experience strong nuclear force, whereas leptons do not.", "Quarks and leptons BOTH experience the weak nuclear force. <--- similarity not needed but good to know.", "Electrically charged quarks and charged leptons experience the electromagnetic force, whereas neutrinos (a type of leptons) do not because they have no electric charge."]}, {"id": "4.3.2.1", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S2 - Particle Interactions", "code": "4.3.2.1", "descriptor": "Describe the concepts of lepton number and baryon number.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Lepton and Baryon numbers are arbitrary quantum numbers assigned to subatomic particles, where, throughout all particle interactions, both Lepton and Baryon numbers must be conserved.", "For lepton number, +1 is assigned to leptons, -1 is assigned to antileptons, and 0 is assigned to non-leptons.", "Additionally, each lepton family has its own quantum number that must also be conserved, e.g. electron-lepton number, tau-lepton number and muon-lepton number.", "For Baryon number, +1/3 is assigned to quarks, -1/3 is assigned to antiquarks, and 0 is assigned to non-baryons."]}, {"id": "4.3.2.2", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S2 - Particle Interactions", "code": "4.3.2.2", "descriptor": "Solve problems relating to the conservation of lepton number and baryon number in particle interactions using equations on the RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.3.2.3", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S2 - Particle Interactions", "code": "4.3.2.3", "descriptor": "Describe electron/electron, electron/positron and neutron decay interactions using particle interaction diagrams.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Electron/electron: Two electrons travel through space and at a point exchange a virtual photon between each other and then scatter away from each other.", "Electron/positron: An electron (e⁻) and a positron (e⁺) travel through space and collide with each other, annihilating into a photon which travels for some time, then pair produces back into an electron and positron.", "Neutron decay: A neutron (udd) travels through space and decays into a proton (uud) and a W⁻ boson.", "The W⁻ boson travels for some time then pair-produces an electron (e⁻) and and electron anti-neutrino (νₑ, with a line on top)"]}, {"id": "4.3.2.4", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S2 - Particle Interactions", "code": "4.3.2.4", "descriptor": "Describe how symmetry in particle interactions occurs to maintain the principles of conservation.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An allowed interaction must preserve the relevant conserved quantities before and after every interaction vertex.", "These include electric charge, spin, baryon number and the specific lepton number for each type.", "Particle interaction diagrams such as the Feynman diagram can represent this balance, where incoming totals equal outgoing totals.", "The symmetry of the interaction laws under particular transformations is linked to conserved quantities, so a proposed interaction is rejected if a required conservation law is broken."]}];
